import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.NinePatch;
import android.graphics.Paint;
import android.graphics.Path;
import android.graphics.Rect;
import android.graphics.RectF;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;

/**
 * Draws a nine-patch whose centre cell is a solid colour and checks that the
 * paint's alpha reaches it.
 *
 * The chat-list search pill is a rounded-rect nine-patch generated by the app
 * (blur3's NinePatchBuilder) and drawn at alpha 0 while its blur is hidden. The
 * colour-cell shortcut in nDrawNinePatch used to replace the paint's colour
 * outright, so that invisible drawable still painted its centre band — a
 * hairline seam across the pill, and across every alert card
 * (BRINGUP_NOTES.md).
 */
public class NinePatchAlphaCheck {
	private static final int BG = 0xff00ff00, FILL = 0xff203040;
	/* the pill's geometry in device pixels at the phone's density 2.625 */
	private static final int RADIUS = 53, DST_W = 900, DST_H = 137;
	private static int failures = 0;

	public static void main(String[] args) {
		NinePatch patch = roundRectPatch(RADIUS, FILL);

		/* an alpha-0 drawable must paint nothing at all */
		Bitmap invisible = draw(patch, 0);
		int stray = 0;
		for (int y = 0; y < DST_H; y++)
			for (int x = 0; x < DST_W; x++)
				if (invisible.getPixel(x, y) != BG)
					stray++;
		if (stray != 0) {
			System.out.println("alpha 0: LEAKS " + stray + " px, e.g. "
				+ hex(invisible.getPixel(DST_W / 2, DST_H / 2)));
			failures++;
		} else {
			System.out.println("alpha 0: nothing painted");
		}

		/* and a faded one must blend its centre cell like the rest: the colour
		 * cell and the image cells above and below it meet in one column */
		for (int alpha : new int[] {128, 255})
			checkUniform(draw(patch, alpha), alpha);

		if (failures != 0) {
			System.out.println("nine-patch alpha check: " + failures + " failure(s)");
			System.exit(1);
		}
		System.out.println("nine-patch alpha check: passed");
	}

	/** Every interior row of the middle column is the same colour — no seam. */
	private static void checkUniform(Bitmap bitmap, int alpha) {
		/* take the reference from an image cell, so that a colour cell that
		 * ignored the alpha is what gets named below */
		int x = DST_W / 2, solid = bitmap.getPixel(x, 4), odd = 0, first = -1;
		/* skip the antialiased top and bottom edges */
		for (int y = 3; y < DST_H - 3; y++) {
			if (bitmap.getPixel(x, y) == solid)
				continue;
			if (first < 0)
				first = y;
			odd++;
		}
		if (odd != 0) {
			System.out.println("alpha " + alpha + ": SEAM of " + odd + " row(s) from y=" + first
				+ ", " + hex(bitmap.getPixel(x, first)) + " against " + hex(solid));
			failures++;
		} else {
			System.out.println("alpha " + alpha + ": uniform " + hex(solid));
		}
	}

	private static Bitmap draw(NinePatch patch, int alpha) {
		Bitmap bitmap = Bitmap.createBitmap(DST_W, DST_H, Bitmap.Config.ARGB_8888);
		Canvas canvas = new Canvas(bitmap);
		canvas.drawColor(BG);
		Paint paint = new Paint();
		paint.setAlpha(alpha);
		canvas.drawPatch(patch, new Rect(0, 0, DST_W, DST_H), paint);
		return bitmap;
	}

	/**
	 * A rounded rect just big enough to hold its corners, with a two-pixel
	 * stretch band in the middle — what NinePatchBuilder produces for a shadowless
	 * background. The centre cell is declared solid so the colour path is taken.
	 */
	private static NinePatch roundRectPatch(int radius, int color) {
		int size = 2 * radius + 2;
		Bitmap bitmap = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888);
		Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
		paint.setColor(color);
		Path path = new Path();
		float[] radii = new float[8];
		java.util.Arrays.fill(radii, radius);
		path.addRoundRect(new RectF(0, 0, size, size), radii, Path.Direction.CW);
		new Canvas(bitmap).drawPath(path, paint);
		return new NinePatch(bitmap, chunk(radius, size - radius, radius, size - radius, color));
	}

	/** The npTc chunk layout, as the platform's NinePatch parses it. */
	private static byte[] chunk(int x1, int x2, int y1, int y2, int centreColor) {
		ByteBuffer buffer = ByteBuffer.allocate(4 + 8 + 16 + 4 + (2 + 2 + 9) * 4)
			.order(ByteOrder.nativeOrder());
		buffer.put((byte)1); // wasSerialized
		buffer.put((byte)2); // numXDivs
		buffer.put((byte)2); // numYDivs
		buffer.put((byte)9); // numColors, (2 + 1) * (2 + 1)
		buffer.putInt(0).putInt(0); // xDivsOffset/yDivsOffset, filled in natively
		buffer.putInt(0).putInt(0).putInt(0).putInt(0); // padding l, r, t, b
		buffer.putInt(0); // colorsOffset
		buffer.putInt(x1).putInt(x2).putInt(y1).putInt(y2);
		for (int cell = 0; cell < 9; cell++)
			buffer.putInt(cell == 4 ? centreColor : 1 /* NO_COLOR */);
		return buffer.array();
	}

	private static String hex(int color) {
		return "#" + Integer.toHexString(color) + " (" + Color.red(color) + ","
			+ Color.green(color) + "," + Color.blue(color) + ")";
	}
}
